// n8n Code node "Request for Claude Code: New Store" in "Store Factory: New Store" (mode: Run Once for All Items).
// The run pauses at the Wait node after this one. A Claude Code session on a DTJ laptop (listen.py watches this workflow too) reads
// `instructions` and does them with the skill dtj-new-store: the store read from its link, the questions and every Approve tap in
// Telegram, the draft copy, the DTJ apps, the brand data and each part chosen (Harsh, 21 Oct 2026: "i just share the brand store link
// and it starts designing the store and it asks the specific questions it needs along with the app installation").
const req = $input.first().json || {};
const link = String(req.link || '').trim();
if (!/^https?:\/\/(?:[A-Za-z0-9-]+\.)+[A-Za-z]{2,}(?:[/?#][^\s]*)?$/.test(link)) throw new Error('No store link reached this step');
const by = String(req.requested_by || 'an admin').trim().slice(0, 60);
const chat = /^-?[0-9]{3,20}$/.test(String(req.chat_id || '').trim()) ? String(req.chat_id).trim() : '';
const note = String(req.note || '').replace(/\s+/g, ' ').trim().slice(0, 500);
const resumeUrl = $execution.resumeUrl;
const q = (s) => '"' + String(s).replace(/"/g, "'") + '"';
const job = 'python n8n/store-factory/store_job.py';
const lines = [
  'DTJ STORE FACTORY - a whole store from one link: ' + link,
  'You are the AI step: a Claude Code session on a DTJ laptop with a person at it (the Shopify CLI there is logged in to DTJ\'s account).',
  '',
  'REQUEST',
  '- Store link: ' + link + (note ? ' | Note from ' + by + ': ' + note : ''),
  '- Asked by: ' + by + ' (an admin on the DTJ bot) | Telegram chat: ' + (chat || '(none: ask the person at this laptop instead)'),
  '- This link is the store to build IN. The job asks: a redesign or a new store, and where the products come from (already in this '
    + 'store, the brand\'s current website, a Google Drive folder, or sample products with ChatGPT pictures). Every product goes in '
    + 'ACTIVE, never as a draft (Harsh, 22 Oct 2026); a price is never made up.',
  '- Every yes comes as an Approve tap in Telegram (Harsh, 21 Oct 2026): one tap for the draft copy, one for the products (copied, '
    + 'from the Drive folder or the samples, with collections and empty policy pages), one for the app copies, one for the header, one for the footer, one for the '
    + 'collection page, one for the About/Contact/FAQ pages, one for the menus. Product and home pages go to the draft under Harsh\'s '
    + 'standing rule. Nothing is published, the live theme is '
    + 'never written, no store is created, and nothing the store has is changed or deleted.',
  '',
  'DO THIS, IN ORDER (from the repo root, D:\\CODE CONTAINERR\\WEB DEV\\dtj-agency-automation)',
  '1. Read CLAUDE.md and the skill dtj-new-store; follow it step by step. Stay on the current git branch.',
  '2. Start: ' + job + ' start --link ' + q(link) + (chat ? ' --chat ' + chat : '') + ' --by ' + q(by),
  '   It reads the store and asks the questions in Telegram. Its JSON line names the job. Exit 3 = waiting for an answer: run it '
    + 'again (it never asks twice); exit 1 = stopped (it says why).',
  '3. The skill\'s steps: a new store\'s samples and banners (store_job.py assets), the draft copy (store_job.py draft), the products '
    + '(store_job.py copy: its Approve tap starts n8n\'s Brand Copy), the apps (store_job.py apps, then installs or add_shop.py), the '
    + 'brand data, then each part chosen, each write after its own Approve tap (store_job.py approve).',
  '4. Answer this n8n run at the end, also when it stopped or is only partly done:',
  '   ' + job + ' finish --job <job> --status "<done | partly done | could not start>" --note "<what is open, in plain words>"',
  '   python n8n/store-factory/reply.py --resume-url "' + resumeUrl + '" --body .work/stores/<job>/answer.json',
  '5. Add a dated entry to docs/HANDOFF.md: the store, what was written where, the samples to replace, what is open.',
  '',
  'RULES',
  '- A write without its Approve tap does not happen; a Skip leaves it undone. One tap covers one action.',
  '- Never invent an offer, price, claim, review or policy: the offer is only the words the person typed; mark samples SAMPLE.',
  '- Never print, paste or store a secret. If something blocks you (the CLI login has no access, the system blocks a command): stop that '
    + 'step, tell the person exactly what to do, and say it in the answer.',
];
return [{ json: {
  claude_code_stage: 'new_store',
  resume_url: resumeUrl,
  instructions: lines.join('\n'),
  request: { link, requested_by: by, telegram_chat_id: chat, note },
} }];

// n8n Code node "Claude Code Reply: New Store" in "Store Factory: New Store" (mode: Run Once for All Items).
// Reads what Claude Code posted to the Wait node (a timeout resumes with no body) and keeps only well-formed values: the same rules as
// n8n/store-factory/reply.py, which refuses a malformed answer before sending it.
const posted = $input.first().json.body;
const b = posted && typeof posted === 'object' && !Array.isArray(posted) ? posted : {};
const allowed = ['done', 'partly done', 'could not start'];
const status = allowed.includes(b.store_status) ? b.store_status : (Object.keys(b).length ? 'reply not understood' : 'timed out (no reply in 7 days)');
const pages = (Array.isArray(b.pages) ? b.pages : []).slice(0, 40)
  .filter((p) => p && /^https:\/\/[a-z0-9.-]+\/\S*$/i.test(String(p.preview || '')))
  .map((p) => ({ part: String(p.part || 'page').slice(0, 60), preview: String(p.preview).slice(0, 400) }));
const req = $('Request for Claude Code: New Store').first().json.request;
return [{ json: {
  link: req.link,
  chat_id: req.telegram_chat_id,
  store_status: status,
  shop: String(b.shop || '').slice(0, 100),
  name: String(b.name || '').slice(0, 100),
  draft_theme_id: /^\d{6,20}$/.test(String(b.draft_theme_id || '')) ? String(b.draft_theme_id) : '',
  pages,
  note: String(b.note || '').slice(0, 800),
} }];

// n8n Code node "Tell the Requester" in "Store Factory: New Store" (mode: Run Once for All Items).
// The result of a whole-store run for the admin who sent the link, with a preview link per page written to the draft.
// Output: [] (no chat) or one { chat_id, text } for "Send Result".
const r = $input.first().json || {};
const chat = String(r.chat_id || '').trim();
if (!chat) return [];
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const attr = (s) => esc(s).replace(/"/g, '&quot;');
const who = esc(r.name || r.link) + (r.shop ? ' (' + esc(r.shop) + ')' : '');
const pages = (r.pages || []).map((p) => '- <a href="' + attr(p.preview) + '">' + esc(p.part) + '</a>').join('\n');
const draft = r.draft_theme_id ? ' in the draft copy (theme ' + esc(r.draft_theme_id) + ', unpublished)' : '';
let text;
if (r.store_status === 'done') {
  text = who + ' is designed' + draft + '. Nothing is published.' + (pages ? '\n\n' + pages : '')
    + (r.note ? '\n\n' + esc(r.note) : '');
} else if (r.store_status === 'partly done') {
  text = who + ' is partly done' + draft + '.' + (r.note ? '\nOpen: ' + esc(r.note) : '') + (pages ? '\n\nReady so far:\n' + pages : '');
} else {
  text = who + ' was not started (' + esc(r.store_status || 'no answer') + ')' + (r.note ? ': ' + esc(r.note) : '.') + '\nHarsh will take a look.';
}
return [{ json: { chat_id: chat, text } }];
